 console.log(JSON.stringify({artifactDirectory:folder}));save();const controller=new AbortController(),deadline=performance.now()+750000,timer=setTimeout(()=>controller.abort(Error('Cohort deadline')),750000);const stop=()=>controller.abort(Error('Process interruption'));process.once('SIGINT',stop);process.once('SIGTERM',stop);const check=()=>{controller.signal.throwIfAborted();assert(performance.now()<deadline);};let transport,adapter;const originalFetch=global.fetch;let external=0,metadata=0,chats=0;
