  transport=createRagWholeEvidenceTransport({phase:'A',record:w=>{state.wire=w;save();},fetch:async(url,options={})=>{check();assert(++external<=13);assert(['http://127.0.0.1:11434/api/tags','http://127.0.0.1:11434/api/chat'].includes(String(url)));if(String(url).endsWith('/api/tags')){assert.equal(++metadata,1);assert.equal(options.method,'GET');}else{assert(++chats<=12);assert.equal(options.method,'POST');checkLoaded(a.pins);adapter.admitWire(options.body);}return originalFetch(url,{...options,redirect:'error',signal:options.signal?AbortSignal.any([controller.signal,options.signal]):controller.signal});}});
